using Meridian.Application.Abstractions;
using Meridian.Application.Triage;
using Meridian.Domain.Jobs;
using Meridian.Domain.Messages;
using Meridian.Domain.Rules;

namespace Meridian.Application.Messages;

public sealed record SubmitMessageCommand(string? Sender, string? Text);

public sealed record SubmitMessageResult(
    Guid? JobId,
    string? Reference,
    IReadOnlyDictionary<string, string[]> Errors)
{
    public bool Succeeded => Errors.Count == 0;

    public static SubmitMessageResult Invalid(IReadOnlyDictionary<string, string[]> errors) => new(null, null, errors);

    public static SubmitMessageResult Created(Guid jobId, string reference) =>
        new(jobId, reference, new Dictionary<string, string[]>());
}

/// <summary>
/// Stores a pasted message unchanged, creates its placeholder job and runs the emergency rules on it, in one
/// transaction, then runs model preparation (<see cref="PrepareJob"/>). The message, job and rule result are saved
/// before the model is called, so a model failure never loses a message or a rule emergency (AD-3, RULE-11).
/// Splitting arrives in a later story.
/// </summary>
public sealed class SubmitMessage
{
    private readonly IJobRepository _jobs;
    private readonly IUnitOfWork _unitOfWork;
    private readonly IClock _clock;
    private readonly PrepareJob _prepareJob;

    public SubmitMessage(IJobRepository jobs, IUnitOfWork unitOfWork, IClock clock, PrepareJob prepareJob)
    {
        _jobs = jobs;
        _unitOfWork = unitOfWork;
        _clock = clock;
        _prepareJob = prepareJob;
    }

    public static IReadOnlyDictionary<string, string[]> Validate(SubmitMessageCommand command)
    {
        var errors = new Dictionary<string, string[]>();
        if (string.IsNullOrWhiteSpace(command.Sender))
        {
            errors["sender"] = new[] { "Sender is required." };
        }

        if (string.IsNullOrWhiteSpace(command.Text))
        {
            errors["text"] = new[] { "Message text is required." };
        }

        return errors;
    }

    public async Task<SubmitMessageResult> ExecuteAsync(SubmitMessageCommand command, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(command);
        var errors = Validate(command);
        if (errors.Count > 0)
        {
            return SubmitMessageResult.Invalid(errors);
        }

        var job = await _unitOfWork.ExecuteAsync(
            async ct =>
            {
                var now = _clock.UtcNow;
                var number = await _jobs.NextJobNumberAsync(ct);
                var message = Message.Receive(command.Sender!, command.Text!, now);
                var created = Job.CreateFromMessage(message, JobReference.FromNumber(number), now);

                // AD-3: emergency rules before the model; they can only raise urgency (AD-4).
                created.ApplyRules(EmergencyRules.Evaluate(message.Text, message.ReceivedAtUtc), now);
                _jobs.Add(created);
                return created;
            },
            cancellationToken);

        // After the commit: the message and any rule emergency are safe whatever the model does (RULE-11).
        await _prepareJob.ExecuteAsync(job.Id, cancellationToken);

        return SubmitMessageResult.Created(job.Id, job.Reference);
    }
}
using System.Text.Json;
using Meridian.Domain.Messages;
using Meridian.Domain.Rules;

namespace Meridian.Domain.Jobs;

/// <summary>
/// One unit of maintenance work. State changes only through methods on this class,
/// and every change appends a <see cref="JobEvent"/> (AD-5).
/// </summary>
public sealed class Job
{
    private readonly List<Message> _messages = new();
    private readonly List<JobEvent> _events = new();

    /// <summary>Fired rule ids, comma-separated, in the order they first fired; stored as the <c>RuleIds</c> column.</summary>
    private string _ruleIds = string.Empty;

    private Job()
    {
        Reference = string.Empty;
    }

    public Guid Id { get; private set; }

    public string Reference { get; private set; }

    public JobStatus Status { get; private set; }

    public Urgency Urgency { get; private set; }

    public Category Category { get; private set; }

    /// <summary>When the job's first message was received (UTC).</summary>
    public DateTime ReceivedAtUtc { get; private set; }

    /// <summary>When the job was opened (UTC).</summary>
    public DateTime CreatedAtUtc { get; private set; }

    /// <summary>Why the job was prepared this way, from the model's proposal (R7). Null until prepared.</summary>
    public string? Explanation { get; private set; }

    /// <summary>English summary of the issue, from the model's proposal. Null until prepared.</summary>
    public string? SummaryEn { get; private set; }

    /// <summary>Language of the tenant's message as reported by the model (e.g. <c>pl</c>). Null until prepared.</summary>
    public string? Language { get; private set; }

    /// <summary>Ids of the emergency rules that fired on this job's messages (see <see cref="EmergencyRuleIds"/>), for the job view.</summary>
    public IReadOnlyList<string> RuleIds =>
        _ruleIds.Length == 0 ? Array.Empty<string>() : _ruleIds.Split(RuleIdSeparator);

    public IReadOnlyList<Message> Messages => _messages;

    public IReadOnlyList<JobEvent> Events => _events;

    /// <summary>
    /// Creates the placeholder job for a freshly received message: status Prepared, category Unsure,
    /// urgency Routine. Appends <see cref="EventType.MessageReceived"/> then <see cref="EventType.JobPrepared"/>.
    /// </summary>
    /// <param name="message">The received message; it becomes the job's first message.</param>
    /// <param name="reference">The job reference, e.g. <c>MER-000001</c>.</param>
    /// <param name="nowUtc">The current time from the application's clock port (AD-9).</param>
    public static Job CreateFromMessage(Message message, string reference, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(message);
        if (string.IsNullOrWhiteSpace(reference) || !reference.StartsWith(JobReference.Prefix, StringComparison.Ordinal))
        {
            throw new ArgumentException("Reference must start with " + JobReference.Prefix + ".", nameof(reference));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (message.JobId is not null)
        {
            throw new InvalidOperationException("Message already belongs to a job.");
        }

        var job = new Job
        {
            Id = Guid.NewGuid(),
            Reference = reference,
            Status = JobStatus.Prepared,
            Urgency = Urgency.Routine,
            Category = Category.Unsure,
            ReceivedAtUtc = message.ReceivedAtUtc,
            CreatedAtUtc = nowUtc,
        };

        message.AttachTo(job.Id);
        job._messages.Add(message);

        job.Append(
            EventType.MessageReceived,
            message.ReceivedAtUtc,
            JobEvent.SystemActor,
            new { messageId = message.Id });

        job.Append(
            EventType.JobPrepared,
            nowUtc,
            JobEvent.SystemActor,
            new
            {
                reference = job.Reference,
                status = job.Status.ToString(),
                urgency = job.Urgency.ToString(),
                category = job.Category.ToString(),
            });

        return job;
    }

    /// <summary>True once a <see cref="EventType.ModelPrepared"/> or <see cref="EventType.ModelPreparationFailed"/> event exists.</summary>
    public bool HasModelOutcome =>
        _events.Any(e => e.Type is EventType.ModelPrepared or EventType.ModelPreparationFailed);

    /// <summary>
    /// Applies a validated model proposal: sets category, explanation, English summary and language, appends
    /// <see cref="EventType.ModelPrepared"/> with <paramref name="payloadJson"/>, then raises urgency to the
    /// proposal (never lowers it, AD-4).
    /// </summary>
    /// <param name="payloadJson">Event payload with the model metadata (model id, prompt version, latency, raw output, attempts).</param>
    public void ApplyModelPreparation(
        Category category,
        Urgency urgency,
        string explanation,
        string summaryEn,
        string language,
        string payloadJson,
        DateTime nowUtc)
    {
        RequireNoModelOutcome();
        if (string.IsNullOrWhiteSpace(explanation))
        {
            throw new ArgumentException("Explanation is required.", nameof(explanation));
        }

        if (string.IsNullOrWhiteSpace(summaryEn))
        {
            throw new ArgumentException("English summary is required.", nameof(summaryEn));
        }

        if (string.IsNullOrWhiteSpace(language))
        {
            throw new ArgumentException("Language is required.", nameof(language));
        }

        RequireJsonObject(payloadJson, nameof(payloadJson));
        Guards.RequireUtc(nowUtc, nameof(nowUtc));

        Category = category;
        Explanation = explanation;
        SummaryEn = summaryEn;
        Language = language;
        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
        RaiseUrgency(urgency, "model", nowUtc);
    }

    /// <summary>
    /// Records that the model gave no usable proposal. The job keeps category Unsure and its urgency (RULE-11).
    /// </summary>
    /// <param name="payloadJson">Event payload with the failure reason, model metadata and validation errors.</param>
    public void RecordModelFailure(string payloadJson, DateTime nowUtc)
    {
        RequireNoModelOutcome();
        RequireJsonObject(payloadJson, nameof(payloadJson));
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        AppendRaw(EventType.ModelPreparationFailed, nowUtc, JobEvent.SystemActor, payloadJson);
    }

    /// <summary>
    /// Records the emergency rules' result for a message (R4): appends <see cref="EventType.RulesApplied"/> listing
    /// each rule id and matched phrase (an empty list when none fired), remembers the fired rule ids, and raises the
    /// job to Emergency with reason <c>rule:&lt;id&gt;</c> of the first hit. Never lowers urgency (AD-4).
    /// </summary>
    /// <param name="hits">The result of <see cref="EmergencyRules.Evaluate"/>.</param>
    public void ApplyRules(IReadOnlyList<RuleHit> hits, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(hits);
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        foreach (var hit in hits)
        {
            if (hit is null || !EmergencyRuleIds.All.Contains(hit.RuleId))
            {
                throw new ArgumentException("Unknown emergency rule.", nameof(hits));
            }
        }

        Append(
            EventType.RulesApplied,
            nowUtc,
            JobEvent.SystemActor,
            new { rules = hits.Select(h => new { id = h.RuleId, matchedPhrase = h.MatchedPhrase }) });

        if (hits.Count == 0)
        {
            return;
        }

        var ruleIds = RuleIds.Concat(hits.Select(h => h.RuleId)).Distinct(StringComparer.Ordinal);
        _ruleIds = string.Join(RuleIdSeparator, ruleIds);
        RaiseUrgency(Urgency.Emergency, RuleReasonPrefix + hits[0].RuleId, nowUtc);
    }

    /// <summary>
    /// The only way urgency goes down (AD-4): a person sets the urgency to <paramref name="level"/>, higher or lower,
    /// and <see cref="EventType.UrgencySetByPerson"/> records who, from what, to what and why. Called from the review
    /// use case only.
    /// </summary>
    /// <param name="actor">The acting person (e.g. Rachel); never the system actor.</param>
    /// <param name="reason">Why the person changed it; required.</param>
    public void SetUrgencyByPerson(Urgency level, string actor, string reason, DateTime nowUtc)
    {
        if (!Enum.IsDefined(level))
        {
            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
        }

        if (string.IsNullOrWhiteSpace(actor) || string.Equals(actor.Trim(), JobEvent.SystemActor, StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException("A person is required.", nameof(actor));
        }

        if (actor.Length > JobEvent.MaxActorLength)
        {
            throw new ArgumentException($"Actor must be at most {JobEvent.MaxActorLength} characters.", nameof(actor));
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required.", nameof(reason));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        var from = Urgency;
        Urgency = level;
        Append(
            EventType.UrgencySetByPerson,
            nowUtc,
            actor,
            new { from = from.ToString(), to = level.ToString(), reason });
    }

    /// <summary>
    /// The only automatic urgency change (AD-4): raises to <paramref name="level"/> and appends
    /// <see cref="EventType.UrgencyRaised"/>; a value lower than or equal to the current urgency is ignored.
    /// </summary>
    /// <returns>True when the urgency changed.</returns>
    public bool RaiseUrgency(Urgency level, string reason, DateTime nowUtc)
    {
        if (!Enum.IsDefined(level))
        {
            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required.", nameof(reason));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (level <= Urgency)
        {
            return false;
        }

        var from = Urgency;
        Urgency = level;
        Append(
            EventType.UrgencyRaised,
            nowUtc,
            JobEvent.SystemActor,
            new { from = from.ToString(), to = level.ToString(), reason });
        return true;
    }

    private const char RuleIdSeparator = ',';
    private const string RuleReasonPrefix = "rule:";

    private void RequireNoModelOutcome()
    {
        if (HasModelOutcome)
        {
            throw new InvalidOperationException("The model outcome for this job is already recorded.");
        }
    }

    private static void RequireJsonObject(string payloadJson, string paramName)
    {
        try
        {
            using var document = JsonDocument.Parse(payloadJson ?? string.Empty);
            if (document.RootElement.ValueKind != JsonValueKind.Object)
            {
                throw new ArgumentException("Payload must be a JSON object.", paramName);
            }
        }
        catch (JsonException ex)
        {
            throw new ArgumentException("Payload must be valid JSON.", paramName, ex);
        }
    }

    private void Append(EventType type, DateTime occurredAtUtc, string actor, object payload) =>
        AppendRaw(type, occurredAtUtc, actor, JsonSerializer.Serialize(payload));

    private void AppendRaw(EventType type, DateTime occurredAtUtc, string actor, string payloadJson) =>
        _events.Add(new JobEvent(Id, type, occurredAtUtc, actor, payloadJson));
}
namespace Meridian.Domain.Jobs;

/// <summary>Job event types, past tense. Later stories add more.</summary>
public enum EventType
{
    MessageReceived,
    JobPrepared,

    /// <summary>The model's proposal was validated and applied to the job.</summary>
    ModelPrepared,

    /// <summary>The model gave no usable proposal; the job stays Unsure (RULE-11, R10).</summary>
    ModelPreparationFailed,

    /// <summary>The job's urgency went up (AD-4).</summary>
    UrgencyRaised,

    /// <summary>The emergency rules ran on a message (R4); the payload lists the rules that fired, possibly none.</summary>
    RulesApplied,

    /// <summary>A person set the job's urgency, up or down, with a reason (AD-4). The only way urgency goes down.</summary>
    UrgencySetByPerson,
}
namespace Meridian.Domain.Jobs;

/// <summary>An append-only history row for a job (AD-5). Never updated or deleted.</summary>
public sealed class JobEvent
{
    public const string SystemActor = "system";

    /// <summary>Length of the stored actor column.</summary>
    public const int MaxActorLength = 64;

    private JobEvent()
    {
        Actor = string.Empty;
        PayloadJson = "{}";
    }

    internal JobEvent(Guid jobId, EventType type, DateTime occurredAtUtc, string actor, string payloadJson)
    {
        Guards.RequireUtc(occurredAtUtc, nameof(occurredAtUtc));
        Id = Guid.NewGuid();
        JobId = jobId;
        Type = type;
        OccurredAtUtc = occurredAtUtc;
        Actor = actor;
        PayloadJson = payloadJson;
    }

    public Guid Id { get; private set; }

    public Guid JobId { get; private set; }

    public EventType Type { get; private set; }

    public DateTime OccurredAtUtc { get; private set; }

    public string Actor { get; private set; }

    public string PayloadJson { get; private set; }
}
namespace Meridian.Domain.Messages;

/// <summary>A tenant message, stored exactly as received (RULE-9). The text is never altered.</summary>
public sealed class Message
{
    private Message()
    {
        Sender = string.Empty;
        Text = string.Empty;
    }

    public Guid Id { get; private set; }

    public Guid? JobId { get; private set; }

    public string Sender { get; private set; }

    public string Text { get; private set; }

    public DateTime ReceivedAtUtc { get; private set; }

    public static Message Receive(string sender, string text, DateTime receivedAtUtc)
    {
        if (string.IsNullOrWhiteSpace(sender))
        {
            throw new ArgumentException("Sender is required.", nameof(sender));
        }

        if (string.IsNullOrWhiteSpace(text))
        {
            throw new ArgumentException("Message text is required.", nameof(text));
        }

        Guards.RequireUtc(receivedAtUtc, nameof(receivedAtUtc));

        return new Message
        {
            Id = Guid.NewGuid(),
            Sender = sender,
            Text = text,
            ReceivedAtUtc = receivedAtUtc,
        };
    }

    internal void AttachTo(Guid jobId) => JobId = jobId;
}
namespace Meridian.Domain.Rules;

/// <summary>One emergency rule that fired on a message: the rule id and the text that matched it.</summary>
/// <param name="RuleId">One of <see cref="EmergencyRuleIds"/>.</param>
/// <param name="MatchedPhrase">The exact span of the message text that matched, as written by the tenant.</param>
public sealed record RuleHit(string RuleId, string MatchedPhrase);

/// <summary>Stable ids of the emergency rules (R4). They are stored on jobs and in events, so never rename one.</summary>
public static class EmergencyRuleIds
{
    public const string Gas = "gas";
    public const string CarbonMonoxide = "carbon-monoxide";
    public const string WaterThroughCeiling = "water-through-ceiling";
    public const string NoHeatingWinter = "no-heating-winter";

    public static readonly IReadOnlyList<string> All = new[] { Gas, CarbonMonoxide, WaterThroughCeiling, NoHeatingWinter };
}
using System.Text.RegularExpressions;

namespace Meridian.Domain.Rules;

/// <summary>
/// The fixed emergency rules (R4, AD-3): plain code, no model call. They run on every message before the model, so
/// they still apply when the model fails (RULE-11).
/// <list type="bullet">
/// <item><c>gas</c>: any mention of gas or a gas smell, in English, Polish, Romanian or Urdu, or gas described
/// without the word (rotten eggs, sulphur).</item>
/// <item><c>carbon-monoxide</c>: carbon monoxide or a CO alarm.</item>
/// <item><c>water-through-ceiling</c>: water, a leak or a drip near a ceiling or a light fitting.</item>
/// <item><c>no-heating-winter</c>: no heating or no hot water, received October to April (UK local month).</item>
/// </list>
/// </summary>
public static class EmergencyRules
{
    /// <summary>First and last UK local month of the winter window, inclusive (October to April).</summary>
    public const int WinterStartMonth = 10;
    public const int WinterEndMonth = 4;

    private const RegexOptions Options = RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled;

    private static readonly TimeZoneInfo London = FindLondon();

    private static readonly (string RuleId, Regex[] Patterns, bool WinterOnly)[] Rules =
    {
        (EmergencyRuleIds.Gas, Compile(EmergencyPhrases.Gas), false),
        (EmergencyRuleIds.CarbonMonoxide, Compile(EmergencyPhrases.CarbonMonoxide), false),
        (EmergencyRuleIds.WaterThroughCeiling, Compile(EmergencyPhrases.WaterThroughCeiling), false),
        (EmergencyRuleIds.NoHeatingWinter, Compile(EmergencyPhrases.NoHeating), true),
    };

    /// <summary>
    /// Evaluates every rule against one message. Returns one hit per rule that fired, in rule order, each with the
    /// exact span of <paramref name="text"/> that matched; an empty list when none fired.
    /// </summary>
    /// <param name="text">The message text as received.</param>
    /// <param name="receivedAtUtc">When the message was received (UTC); its Europe/London month sets the winter window.</param>
    public static IReadOnlyList<RuleHit> Evaluate(string text, DateTime receivedAtUtc)
    {
        ArgumentNullException.ThrowIfNull(text);
        Guards.RequireUtc(receivedAtUtc, nameof(receivedAtUtc));

        var winter = IsWinter(receivedAtUtc);
        var hits = new List<RuleHit>();
        foreach (var (ruleId, patterns, winterOnly) in Rules)
        {
            if (winterOnly && !winter)
            {
                continue;
            }

            foreach (var pattern in patterns)
            {
                var match = pattern.Match(text);
                if (match.Success)
                {
                    hits.Add(new RuleHit(ruleId, match.Value.Trim()));
                    break;
                }
            }
        }

        return hits;
    }

    /// <summary>True when <paramref name="receivedAtUtc"/> falls in October to April, UK local time.</summary>
    public static bool IsWinter(DateTime receivedAtUtc)
    {
        Guards.RequireUtc(receivedAtUtc, nameof(receivedAtUtc));
        var month = TimeZoneInfo.ConvertTimeFromUtc(receivedAtUtc, London).Month;
        return month >= WinterStartMonth || month <= WinterEndMonth;
    }

    private static Regex[] Compile(IEnumerable<string> patterns) =>
        patterns.Select(p => new Regex(p, Options)).ToArray();

    private static TimeZoneInfo FindLondon()
    {
        foreach (var id in new[] { "Europe/London", "GMT Standard Time" })
        {
            try
            {
                return TimeZoneInfo.FindSystemTimeZoneById(id);
            }
            catch (TimeZoneNotFoundException)
            {
            }
            catch (InvalidTimeZoneException)
            {
            }
        }

        // No time-zone data on this machine: the UK rule since 1996 (BST from 01:00 UTC on the last Sunday of March
        // to 01:00 UTC on the last Sunday of October).
        var rule = TimeZoneInfo.AdjustmentRule.CreateAdjustmentRule(
            DateTime.MinValue.Date,
            DateTime.MaxValue.Date,
            TimeSpan.FromHours(1),
            TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new DateTime(1, 1, 1, 1, 0, 0), 3, 5, DayOfWeek.Sunday),
            TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new DateTime(1, 1, 1, 2, 0, 0), 10, 5, DayOfWeek.Sunday));
        return TimeZoneInfo.CreateCustomTimeZone("Europe/London", TimeSpan.Zero, "UK", "GMT", "BST", new[] { rule });
    }
}
namespace Meridian.Application.Abstractions;

/// <summary>The only source of time (AD-9). Always returns UTC.</summary>
public interface IClock
{
    DateTime UtcNow { get; }
}
using Meridian.Domain.Jobs;

namespace Meridian.Application.Abstractions;

public interface IJobRepository
{
    /// <summary>Takes the next job number from the reference sequence. Call inside a unit of work.</summary>
    Task<long> NextJobNumberAsync(CancellationToken cancellationToken);

    /// <summary>Tracks a new job with its messages and events; written when the unit of work commits.</summary>
    void Add(Job job);

    /// <summary>One job with its messages and events, tracked for changes; null when it does not exist.</summary>
    Task<Job?> GetAsync(Guid id, CancellationToken cancellationToken);

    /// <summary>All jobs with their messages, read-only.</summary>
    Task<IReadOnlyList<Job>> ListAsync(CancellationToken cancellationToken);
}
namespace Meridian.Application.Abstractions;

/// <summary>Runs work in one database transaction and saves everything it tracked (AD-5).</summary>
public interface IUnitOfWork
{
    Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> work, CancellationToken cancellationToken);
}

using Meridian.Domain.Jobs;
using Meridian.Domain.Messages;
using Microsoft.EntityFrameworkCore;

namespace Meridian.Infrastructure.Persistence;

public sealed class MeridianDbContext : DbContext
{
    public MeridianDbContext(DbContextOptions<MeridianDbContext> options)
        : base(options)
    {
    }

    public DbSet<Job> Jobs => Set<Job>();

    public DbSet<Message> Messages => Set<Message>();

    public DbSet<JobEvent> JobEvents => Set<JobEvent>();

    public DbSet<JobNumberSequence> JobNumberSequences => Set<JobNumberSequence>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Enums are stored as their names, never numbers.
        configurationBuilder.Properties<Enum>().HaveConversion<string>();
        configurationBuilder.Properties<DateTime>().HaveConversion<UtcDateTimeConverter>();
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(MeridianDbContext).Assembly);
    }
}
using Meridian.Domain.Jobs;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Meridian.Infrastructure.Persistence.Configurations;

internal sealed class JobConfiguration : IEntityTypeConfiguration<Job>
{
    public void Configure(EntityTypeBuilder<Job> builder)
    {
        builder.ToTable("Jobs");
        builder.HasKey(j => j.Id);
        builder.Property(j => j.Id).ValueGeneratedNever();
        builder.Property(j => j.Reference).IsRequired().HasMaxLength(16);
        builder.HasIndex(j => j.Reference).IsUnique();
        builder.Property(j => j.Status).IsRequired().HasMaxLength(32);
        builder.Property(j => j.Urgency).IsRequired().HasMaxLength(32);
        builder.Property(j => j.Category).IsRequired().HasMaxLength(32);
        builder.Property(j => j.ReceivedAtUtc).IsRequired();
        builder.Property(j => j.CreatedAtUtc).IsRequired();
        builder.Property(j => j.Explanation);
        builder.Property(j => j.SummaryEn);
        builder.Property(j => j.Language).HasMaxLength(16);
        builder.Ignore(j => j.HasModelOutcome);

        // Fired emergency rule ids, comma-separated (e.g. "gas,carbon-monoxide"); empty when none fired.
        builder.Ignore(j => j.RuleIds);
        builder.Property<string>("_ruleIds")
            .HasField("_ruleIds")
            .UsePropertyAccessMode(PropertyAccessMode.Field)
            .HasColumnName("RuleIds")
            .IsRequired()
            .HasMaxLength(256)
            .HasDefaultValue(string.Empty);

        builder.HasMany(j => j.Messages)
            .WithOne()
            .HasForeignKey(m => m.JobId)
            .OnDelete(DeleteBehavior.Restrict);
        builder.Navigation(j => j.Messages).UsePropertyAccessMode(PropertyAccessMode.Field);

        builder.HasMany(j => j.Events)
            .WithOne()
            .HasForeignKey(e => e.JobId)
            .OnDelete(DeleteBehavior.Restrict);
        builder.Navigation(j => j.Events).UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}
